import { AppText as Text } from '@makanza/mobile-ui';
import { Pressable, StyleSheet, View } from 'react-native';
import type { VendorOrder } from '@makanza/mobile-core';

type Props={order:VendorOrder;busy:boolean;dark:boolean;onAction:(id:string,status:string)=>void};
export default function OrderCard({order,busy,dark,onAction}:Props){
  const next=order.status==='CONFIRMED'?['Accept order','ACCEPTED_BY_VENDOR']:order.status==='ACCEPTED_BY_VENDOR'?['Start preparing','PREPARING']:order.status==='PREPARING'?['Ready for pickup','READY_FOR_PICKUP']:null;
  return <View style={[s.card,dark&&s.cardDark]}>
    <View style={s.row}><Text style={[s.id,dark&&s.lightText]}>Order {order.id.slice(-8)}</Text><Text style={s.status}>{order.status.replaceAll('_',' ').toLowerCase()}</Text></View>
    <Text style={[s.items,dark&&s.mutedDark]}>{order.items.map(line=>`${line.quantity} × ${line.nameSnapshot}${line.addons?.length?` (+ ${line.addons.map(extra=>`${extra.quantity*line.quantity} ${extra.nameSnapshot}`).join(', ')})`:''}`).join(' · ')}</Text>
    <View style={s.row}><Text style={[s.date,dark&&s.mutedDark]}>{new Date(order.createdAt).toLocaleString()}</Text><Text style={s.total}>₦{(order.totalMinor/100).toLocaleString('en-NG')}</Text></View>
    {order.delivery?.pickupCode&&<View style={s.pickupCode}><Text style={s.pickupLabel}>RIDER PICKUP CODE</Text><Text style={s.pickupValue}>{order.delivery.pickupCode}</Text><Text style={[s.date,dark&&s.mutedDark]}>Share with your assigned rider when handing over this order.</Text></View>}
    {next&&<View style={s.actions}>{order.status==='CONFIRMED'&&<Pressable accessibilityRole="button" onPress={()=>onAction(order.id,'REJECTED')} disabled={busy} style={s.reject}><Text style={s.rejectText}>Reject</Text></Pressable>}<Pressable accessibilityRole="button" onPress={()=>onAction(order.id,next[1])} disabled={busy} style={[s.button,busy&&s.disabled]}><Text style={s.buttonText}>{busy?'Updating…':next[0]}</Text></Pressable></View>}
  </View>;
}
const s=StyleSheet.create({card:{padding:15,backgroundColor:'white',borderColor:'#e8ebe2',borderWidth:1,borderRadius:17,gap:11},cardDark:{backgroundColor:'#18251c',borderColor:'#2a382f'},row:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',gap:10},id:{fontSize:15,fontWeight:'800',color:'#192b23'},status:{fontSize:11,color:'#194c3a',backgroundColor:'#eef3e4',paddingHorizontal:8,paddingVertical:5,borderRadius:8,textTransform:'capitalize'},items:{fontSize:13,lineHeight:21,color:'#69766a'},date:{fontSize:11,color:'#79817a',flex:1},total:{fontSize:13,fontWeight:'900',color:'#194c3a'},pickupCode:{padding:12,borderRadius:12,backgroundColor:'#eef3e4',gap:4},pickupLabel:{fontSize:10,fontWeight:'900',letterSpacing:1,color:'#194c3a'},pickupValue:{fontSize:26,letterSpacing:5,fontWeight:'900',color:'#192b23'},actions:{flexDirection:'row',gap:8,justifyContent:'flex-end',marginTop:3},button:{minHeight:41,paddingHorizontal:15,borderRadius:12,backgroundColor:'#194c3a',justifyContent:'center',alignItems:'center'},buttonText:{fontSize:12,fontWeight:'800',color:'white'},reject:{minHeight:41,paddingHorizontal:15,borderRadius:12,borderWidth:1,borderColor:'#e3ded8',justifyContent:'center'},rejectText:{fontSize:12,fontWeight:'800',color:'#994739'},disabled:{opacity:.55},lightText:{color:'#edf3e9'},mutedDark:{color:'#aab4a8'}});
